=== FILE: rr_arbiter.v ===
// rr_arbiter: round-robin arbiter for N requesters (default 4).
// Implements interface_spec.md and microarchitecture.md (case rtl/rr-arbiter).
//   * At most one grant per cycle, only to a requester, work conserving.
//   * grant is combinational from req and the priority pointer ptr.
//   * On every rising edge with a grant, ptr moves to one past the winner,
//     wrapping explicitly from N-1 to 0 (N need not be a power of two).
//     With no request, ptr holds.
//   * rst_n is active low and synchronous; ptr resets to 0. grant is not
//     gated by reset.
module rr_arbiter #(
  parameter integer N = 4
) (
  input  wire         clk,
  input  wire         rst_n,
  input  wire [N-1:0] req,
  output reg  [N-1:0] grant
);

  localparam integer  PW     = $clog2(N);
  localparam integer  LAST_I = N - 1;
  localparam integer  ONE_I  = 1;
  localparam [PW-1:0] LAST   = LAST_I[PW-1:0];
  localparam [PW-1:0] ONE    = ONE_I[PW-1:0];
  localparam [PW-1:0] ZERO   = {PW{1'b0}};
  localparam [N-1:0]  ONEV   = {{(N-1){1'b0}}, 1'b1};
  localparam [N-1:0]  NONEV  = {N{1'b0}};

  // Priority pointer: index of the requester with the highest priority.
  reg [PW-1:0] ptr;
  reg [PW-1:0] ptr_next;
  reg [PW-1:0] idx;
  reg [PW-1:0] winner;
  reg          found;
  integer      i;

  // Wrapping priority search from ptr upwards; all outputs defaulted first.
  always @* begin
    found  = 1'b0;
    winner = ptr;
    idx    = ptr;
    for (i = 0; i < N; i = i + 1) begin
      if (!found && req[idx]) begin
        found  = 1'b1;
        winner = idx;
      end
      if (idx == LAST) begin
        idx = ZERO;
      end else begin
        idx = idx + ONE;
      end
    end

    if (found) begin
      grant = ONEV << winner;
    end else begin
      grant = NONEV;
    end

    if (!found) begin
      ptr_next = ptr;
    end else if (winner == LAST) begin
      ptr_next = ZERO;
    end else begin
      ptr_next = winner + ONE;
    end
  end

  // Pointer register: reset value and update only.
  always @(posedge clk) begin
    if (!rst_n) begin
      ptr <= ZERO;
    end else begin
      ptr <= ptr_next;
    end
  end

`ifdef FORMAL
  // ---------------------------------------------------------------------
  // Design-intent properties (read with read -formal).
  // ---------------------------------------------------------------------
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge clk) f_past_valid <= 1'b1;

  // Reset is active in the first cycle.
  always @(*) begin
    if (!f_past_valid) assume(!rst_n);
  end

  // Circular distance from 'from' up to 'to', modulo N.
  function [31:0] f_dist;
    input [31:0] from;
    input [31:0] to;
    begin
      if (to >= from) f_dist = to - from;
      else            f_dist = to + N - from;
    end
  endfunction

  reg [31:0] f_wdist;
  always @(*) f_wdist = f_dist(ptr, winner);

  // Pointer in range; grant one-hot or zero, only to a requester, work
  // conserving.
  always @(*) begin
    if (f_past_valid) begin
      assert(ptr <= LAST);
      assert((grant & (grant - ONEV)) == NONEV);
      assert((grant & ~req) == NONEV);
      if (req != NONEV) assert(grant != NONEV);
      if (found) assert(winner <= LAST);
    end
  end

  // Pointer update: 0 after reset, one past the winner after a grant,
  // unchanged with no request.
  always @(posedge clk) begin
    if (f_past_valid) begin
      if (!$past(rst_n))              assert(ptr == ZERO);
      else if (!$past(found))         assert(ptr == $past(ptr));
      else if ($past(winner) == LAST) assert(ptr == ZERO);
      else                            assert(ptr == $past(winner) + ONE);
    end
  end

  // Pointer wraps from N-1 to 0 by a grant (not by reset).
  always @(posedge clk) begin
    if (f_past_valid) cover($past(rst_n) && ($past(ptr) == LAST) && (ptr == ZERO));
  end

  // Everyone requesting at once.
  always @(*) begin
    if (f_past_valid && rst_n) cover(req == {N{1'b1}});
  end

  genvar g;
  generate
    for (g = 0; g < N; g = g + 1) begin : g_fv
      // Cycles requester g has waited with its request held.
      reg [PW+1:0] f_wait;
      reg [31:0]   f_rdist;

      always @(*) f_rdist = f_dist(ptr, g);

      always @(posedge clk) begin
        if (!rst_n || !req[g] || grant[g]) f_wait <= {(PW+2){1'b0}};
        else                               f_wait <= f_wait + 1'b1;
      end

      always @(*) begin
        if (f_past_valid) begin
          // Starvation bound: a held request waits at most N-1 cycles.
          assert(f_wait <= LAST);
          // Induction invariant: wait plus pointer distance stays within N-1.
          assert(f_wait + f_rdist <= LAST_I);
          // Round-robin order: no requester between the pointer and the winner.
          if (req[g]) assert(found && (f_wdist <= f_rdist));
        end
      end

      always @(*) begin
        if (f_past_valid && rst_n) begin
          cover(grant[g]);
          cover(req[g] && (f_wait == LAST));
        end
      end
    end
  endgenerate
`endif

endmodule
=== END FILE ===
=== FILE: rr_arbiter_tb.v ===
// rr_arbiter_tb: self-checking testbench for rr_arbiter.
// Two arbiters run side by side, N=4 (default) and N=5 (not a power of two),
// each checked every cycle against a reference pointer model, with
// per-requester wait counters and coverage counters that fail the run if a
// case required by interface_spec.md section 6 was not reached.

module rr_arbiter_tb_unit #(
  parameter integer N    = 4,
  parameter integer SEED = 1
) (
  output reg        done,
  output reg [31:0] passed,
  output reg [31:0] failed
);
  localparam [N-1:0] ONEV  = {{(N-1){1'b0}}, 1'b1};
  localparam [N-1:0] ALLV  = {N{1'b1}};
  localparam [N-1:0] NONEV = {N{1'b0}};

  reg          clk;
  reg          rst_n;
  reg  [N-1:0] req;
  wire [N-1:0] grant;

  rr_arbiter #(.N(N)) dut (
    .clk   (clk),
    .rst_n (rst_n),
    .req   (req),
    .grant (grant)
  );

  // Reference model and bookkeeping
  integer     mptr;
  integer     exp_win;
  reg [N-1:0] exp_grant;
  integer     wait_cnt  [0:N-1];
  integer     cov_alone [0:N-1];
  integer     cov_none;
  integer     cov_all;
  integer     cov_maxwait;
  integer     cov_held;
  integer     cov_rst_traffic;
  integer     cov_wrap;
  integer     cov_rot;
  integer     held;
  integer     rot;
  reg [31:0]  lcg;
  integer     i;
  integer     r;
  integer     s;
  integer     k;
  integer     idx;

  task note_pass;
    begin
      passed = passed + 32'd1;
    end
  endtask

  task note_fail;
    begin
      failed = failed + 32'd1;
    end
  endtask

  // Expected winner: first requester at or after mptr, wrapping at N.
  task model_eval;
    begin
      exp_win   = -1;
      exp_grant = NONEV;
      for (s = 0; s < N; s = s + 1) begin
        idx = mptr + s;
        if (idx >= N) idx = idx - N;
        if ((exp_win < 0) && req[idx]) exp_win = idx;
      end
      if (exp_win >= 0) exp_grant = ONEV << exp_win;
    end
  endtask

  task check_cycle;
    begin
      model_eval;

      // Grant against the reference pointer model.
      if (grant === exp_grant) begin
        note_pass;
      end else begin
        note_fail;
        $error("rr_arbiter N=%0d t=%0t: grant=%b expected %b (req=%b model ptr=%0d rst_n=%b)",
               N, $time, grant, exp_grant, req, mptr, rst_n);
      end

      // One-hot or zero, and only to a requester (independent of the model).
      if (((grant & (grant - ONEV)) == NONEV) && ((grant & ~req) == NONEV)) begin
        note_pass;
      end else begin
        note_fail;
        $error("rr_arbiter N=%0d t=%0t: grant=%b is not one-hot-or-zero within req=%b",
               N, $time, grant, req);
      end

      // Work conserving.
      if ((req != NONEV) == (grant != NONEV)) begin
        note_pass;
      end else begin
        note_fail;
        $error("rr_arbiter N=%0d t=%0t: not work conserving, req=%b grant=%b",
               N, $time, req, grant);
      end

      // Strict rotation 0, 1, ..., N-1 after reset with everyone requesting.
      if (rot >= 0) begin
        if (grant === (ONEV << rot)) begin
          note_pass;
          cov_rot = cov_rot + 1;
        end else begin
          note_fail;
          $error("rr_arbiter N=%0d t=%0t: rotation after reset, grant=%b expected requester %0d",
                 N, $time, grant, rot);
        end
      end

      // Fairness: no held request waits N cycles.
      for (k = 0; k < N; k = k + 1) begin
        if (!rst_n || !req[k] || grant[k]) begin
          if (rst_n && req[k] && grant[k] && (wait_cnt[k] == N - 1))
            cov_maxwait = cov_maxwait + 1;
          wait_cnt[k] = 0;
        end else begin
          wait_cnt[k] = wait_cnt[k] + 1;
          if (wait_cnt[k] <= N - 1) begin
            note_pass;
          end else begin
            note_fail;
            $error("rr_arbiter N=%0d t=%0t: requester %0d has waited %0d cycles (bound %0d)",
                   N, $time, k, wait_cnt[k], N - 1);
          end
        end
      end

      // Coverage.
      if (rst_n) begin
        if (req == NONEV) cov_none = cov_none + 1;
        if (req == ALLV)  cov_all  = cov_all + 1;
        for (k = 0; k < N; k = k + 1) begin
          if (req == (ONEV << k)) cov_alone[k] = cov_alone[k] + 1;
        end
        if ((held >= 0) && (wait_cnt[held] > 0)) cov_held = cov_held + 1;
        if (exp_win == N - 1) cov_wrap = cov_wrap + 1;
      end else begin
        if ((req != NONEV) && (mptr != 0)) cov_rst_traffic = cov_rst_traffic + 1;
      end
    end
  endtask

  // One clock cycle: settle, check, rising edge, update the model.
  task cycle;
    begin
      #5;
      check_cycle;
      clk = 1'b1;
      if (!rst_n) begin
        mptr = 0;
      end else if (exp_win >= 0) begin
        mptr = (exp_win == N - 1) ? 0 : exp_win + 1;
      end
      if ((rot >= 0) && rst_n) rot = (rot == N - 1) ? 0 : rot + 1;
      #5;
      clk = 1'b0;
    end
  endtask

  task next_rand;
    begin
      lcg = lcg * 32'd1664525 + 32'd1013904223;
    end
  endtask

  initial begin
    done            = 1'b0;
    passed          = 32'd0;
    failed          = 32'd0;
    clk             = 1'b0;
    rst_n           = 1'b0;
    req             = NONEV;
    mptr            = 0;
    exp_win         = -1;
    exp_grant       = NONEV;
    held            = -1;
    rot             = -1;
    lcg             = SEED;
    cov_none        = 0;
    cov_all         = 0;
    cov_maxwait     = 0;
    cov_held        = 0;
    cov_rst_traffic = 0;
    cov_wrap        = 0;
    cov_rot         = 0;
    for (k = 0; k < N; k = k + 1) begin
      wait_cnt[k]  = 0;
      cov_alone[k] = 0;
    end

    // Reset with no requests.
    cycle;
    cycle;
    rst_n = 1'b1;

    // No requests.
    repeat (3) cycle;

    // Each requester alone, held for two cycles, then dropped.
    for (i = 0; i < N; i = i + 1) begin
      req = ONEV << i;
      cycle;
      cycle;
      req = NONEV;
      cycle;
    end

    // Everyone requesting for several rounds.
    req = ALLV;
    for (r = 0; r < 3 * N; r = r + 1) cycle;

    // Longest fair wait, directed: pointer to 1, then everyone requests;
    // requester 0 waits N-1 cycles.
    req = ONEV;
    cycle;
    req = ALLV;
    for (r = 0; r < N; r = r + 1) cycle;

    // A held request among changing others.
    for (i = 0; i < N; i = i + 1) begin
      held = i;
      for (r = 0; r < 4 * N; r = r + 1) begin
        next_rand;
        req    = lcg[16 +: N];
        req[i] = 1'b1;
        cycle;
      end
    end
    held = -1;

    // Random subsets: requests dropped and raised again.
    for (r = 0; r < 40 * N; r = r + 1) begin
      next_rand;
      req = lcg[16 +: N];
      cycle;
    end

    // Reset during traffic, then strict rotation from requester 0.
    req = ONEV;
    cycle;
    req = ALLV;
    cycle;
    rst_n = 1'b0;
    cycle;
    cycle;
    rst_n = 1'b1;
    rot   = 0;
    for (r = 0; r < 2 * N; r = r + 1) cycle;
    rot = -1;

    // Random traffic with occasional resets.
    for (r = 0; r < 20 * N; r = r + 1) begin
      next_rand;
      req   = lcg[16 +: N];
      rst_n = (lcg[27:24] != 4'd0);
      cycle;
    end
    rst_n = 1'b1;
    req   = NONEV;
    cycle;

    // Coverage: every required case must have been reached.
    if (cov_none > 0) note_pass;
    else begin note_fail; $error("rr_arbiter N=%0d: coverage hole: no requests", N); end
    if (cov_all > 0) note_pass;
    else begin note_fail; $error("rr_arbiter N=%0d: coverage hole: everyone requesting", N); end
    for (k = 0; k < N; k = k + 1) begin
      if (cov_alone[k] > 0) note_pass;
      else begin note_fail; $error("rr_arbiter N=%0d: coverage hole: requester %0d alone", N, k); end
    end
    if (cov_maxwait > 0) note_pass;
    else begin note_fail; $error("rr_arbiter N=%0d: coverage hole: longest fair wait of N-1 cycles", N); end
    if (cov_held > 0) note_pass;
    else begin note_fail; $error("rr_arbiter N=%0d: coverage hole: held request among changing others", N); end
    if (cov_rst_traffic > 0) note_pass;
    else begin note_fail; $error("rr_arbiter N=%0d: coverage hole: reset during traffic", N); end
    if (cov_wrap > 0) note_pass;
    else begin note_fail; $error("rr_arbiter N=%0d: coverage hole: pointer wrap from N-1 to 0", N); end
    if (cov_rot >= 2 * N) note_pass;
    else begin note_fail; $error("rr_arbiter N=%0d: coverage hole: strict rotation after reset", N); end

    done = 1'b1;
  end
endmodule

module rr_arbiter_tb;
  wire           done4;
  wire           done5;
  wire [31:0]    passed4;
  wire [31:0]    failed4;
  wire [31:0]    passed5;
  wire [31:0]    failed5;
  reg  [8*64-1:0] nonce;
  integer        has_nonce;
  integer        passed;
  integer        failed;

  rr_arbiter_tb_unit #(.N(4), .SEED(12345)) u_n4 (
    .done   (done4),
    .passed (passed4),
    .failed (failed4)
  );

  rr_arbiter_tb_unit #(.N(5), .SEED(67891)) u_n5 (
    .done   (done5),
    .passed (passed5),
    .failed (failed5)
  );

  initial begin
    nonce     = {(8*64){1'b0}};
    has_nonce = $value$plusargs("nirmaan_nonce=%s", nonce);
    while (!(done4 && done5)) #10;
    passed = passed4 + passed5;
    failed = failed4 + failed5;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end
endmodule
